class TestModelsUrl:
    def test_appends_v1_models(self):
        assert (
            models_url("https://provider.example")
            == "https://provider.example/v1/models?limit=1000"
        )

    def test_does_not_duplicate_v1(self):
        assert (
            models_url("https://provider.example/v1/")
            == "https://provider.example/v1/models?limit=1000"
        )

    def test_keeps_base_path(self):
        assert (
            models_url("https://provider.example/api")
            == "https://provider.example/api/v1/models?limit=1000"
        )

    def test_rejects_relative_url(self):
        with pytest.raises(RefreshError):
            models_url("/v1")


class TestAuthHeaders:
    def test_explicit_token_defaults_to_api_key(self):
        headers = auth_headers(token="secret")
        assert headers["x-api-key"] == "secret"
        assert "Authorization" not in headers

    def test_explicit_token_can_use_bearer(self):
        headers = auth_headers(token="secret", auth="bearer")
        assert headers["Authorization"] == "Bearer secret"
        assert "x-api-key" not in headers

    def test_reads_api_key_environment(self, monkeypatch):
        monkeypatch.setenv("ANTHROPIC_API_KEY", "api-key")
        monkeypatch.setenv("ANTHROPIC_AUTH_TOKEN", "bearer")
        headers = auth_headers()
        assert headers["x-api-key"] == "api-key"
        assert "Authorization" not in headers

    def test_reads_bearer_environment_when_api_key_is_absent(self, monkeypatch):
        monkeypatch.delenv("ANTHROPIC_API_KEY", raising=False)
        monkeypatch.setenv("ANTHROPIC_AUTH_TOKEN", "bearer")
        headers = auth_headers()
        assert headers["Authorization"] == "Bearer bearer"
        assert "x-api-key" not in headers

    def test_explicit_auth_does_not_fall_back_to_the_other_env(self, monkeypatch):
        monkeypatch.delenv("ANTHROPIC_API_KEY", raising=False)
        monkeypatch.setenv("ANTHROPIC_AUTH_TOKEN", "bearer")
        with pytest.raises(RefreshError):
            auth_headers(auth="api-key")

    def test_requires_a_credential(self, monkeypatch):
        monkeypatch.delenv("ANTHROPIC_AUTH_TOKEN", raising=False)
        monkeypatch.delenv("ANTHROPIC_API_KEY", raising=False)
        with pytest.raises(RefreshError):
            auth_headers()


