class TestLatestByClass:
    def test_keeps_highest_numeric_version(self):
        options = [
            {"model": "claude-haiku-4-5"},
            {"model": "claude-haiku-5-5"},
            {"model": "claude-haiku-5"},
        ]
        assert latest_by_class(options) == [{"model": "claude-haiku-5-5"}]

    def test_compares_multi_digit_components_numerically(self):
        options = [
            {"model": "m-5-2"},
            {"model": "m-5-10"},
        ]
        assert latest_by_class(options) == [{"model": "m-5-10"}]

    def test_treats_more_components_as_newer(self):
        options = [
            {"model": "m-5"},
            {"model": "m-5-5"},
        ]
        assert latest_by_class(options) == [{"model": "m-5-5"}]

    def test_falls_back_to_lexicographic_comparison(self):
        options = [
            {"model": "model-4.1-Flash-1017"},
            {"model": "model-4.1-Flash-1018"},
        ]
        assert latest_by_class(options) == [{"model": "model-4.1-Flash-1018"}]

    def test_keeps_first_seen_class_order(self):
        options = [
            {"model": "opus-5"},
            {"model": "sonnet-5"},
            {"model": "opus-6"},
        ]
        assert latest_by_class(options) == [
            {"model": "opus-6"},
            {"model": "sonnet-5"},
        ]


