class TestBuildOptions:
    def test_uses_display_name_when_it_differs(self):
        options = build_options(
            [{"id": "model-1", "display_name": "Model One"}],
        )
        assert options == [{"model": "model-1", "label": "Model One"}]

    def test_generates_label_when_display_name_matches_id(self):
        options = build_options([{"id": "model-1", "display_name": "model-1"}])
        assert options == [{"model": "model-1", "label": "model 1"}]

    def test_deduplicates_and_skips_bad_entries(self):
        options = build_options(
            [
                {"id": "model-1"},
                {"id": "model-1"},
                {"id": ""},
                {"display_name": "no id"},
                "not an object",
            ],
        )
        assert options == [{"model": "model-1", "label": "model 1"}]

    def test_keeps_only_the_latest_of_each_model_class(self):
        options = build_options(
            [
                {"id": "acme/haiku-4-5"},
                {"id": "acme/opus-5"},
                {"id": "acme/haiku-5-5"},
                {"id": "acme/opus-5-5"},
            ],
        )
        assert [row["model"] for row in options] == [
            "acme/haiku-5-5",
            "acme/opus-5-5",
        ]

    def test_excludes_anthropic_models_by_default(self):
        options = build_options([{"id": "claude-opus-5"}, {"id": "acme/opus-5"}])
        assert [row["model"] for row in options] == ["acme/opus-5"]

    def test_can_include_anthropic_models(self):
        options = build_options(
            [{"id": "claude-opus-5"}],
            include_anthropic=True,
        )
        assert options == [{"model": "claude-opus-5", "label": "claude opus 5"}]

    def test_adds_description(self):
        options = build_options(
            [{"id": "model-1"}],
            description="Hosted via Example",
        )
        assert options == [
            {
                "model": "model-1",
                "label": "model 1",
                "description": "Hosted via Example",
            }
        ]

    def test_rejects_an_empty_result(self):
        with pytest.raises(RefreshError):
            build_options([{"display_name": "no id"}])


class TestSettingsDocument:
    def test_replaces_options_and_preserves_other_keys(self, tmp_path):
        settings = tmp_path / "settings.json"
        settings.write_text(
            json.dumps(
                {
                    "model": "old",
                    "modelPicker": {
                        "replaceBuiltInOptions": True,
                        "options": [{"model": "stale"}],
                    },
                }
            )
        )

        document = _settings_document(settings, [{"model": "fresh"}])

        assert document["model"] == "old"
        assert document["modelPicker"] == {
            "replaceBuiltInOptions": True,
            "options": [{"model": "fresh"}],
        }

    def test_creates_model_picker_when_absent(self, tmp_path):
        settings = tmp_path / "settings.json"
        settings.write_text(json.dumps({"model": "old"}))

        document = _settings_document(settings, [{"model": "fresh"}])

        assert document["modelPicker"] == {"options": [{"model": "fresh"}]}

    def test_rejects_invalid_json(self, tmp_path):
        settings = tmp_path / "settings.json"
        settings.write_text("{")

        with pytest.raises(RefreshError):
            _settings_document(settings, [{"model": "fresh"}])


class TestMain:
    def test_dry_run_prints_without_writing(self, tmp_path, capsys):
        settings = tmp_path / "settings.json"
        settings.write_text(json.dumps({"model": "old"}))

        with mock.patch(
            "scripts.refresh_models.fetch_models",
            return_value=[{"id": "model-1"}],
        ):
            result = main(
                [
                    "--url",
                    "https://provider.example",
                    "--token",
                    "secret",
                    "--settings",
                    str(settings),
                    "--dry-run",
                ]
            )

        assert result == 0
        assert json.loads(capsys.readouterr().out)["modelPicker"] == {
            "options": [{"model": "model-1", "label": "model 1"}]
        }
        assert json.loads(settings.read_text()) == {"model": "old"}

    def test_updates_settings(self, tmp_path, capsys):
        settings = tmp_path / "settings.json"
        settings.write_text(
            json.dumps({"model": "old", "modelPicker": {"options": []}})
        )

        with mock.patch(
            "scripts.refresh_models.fetch_models",
            return_value=[{"id": "model-1"}],
        ):
            result = main(
                [
                    "--url",
                    "https://provider.example",
                    "--token",
                    "secret",
                    "--settings",
                    str(settings),
                ]
            )

        assert result == 0
        assert "Refreshed 1 models" in capsys.readouterr().out
        document = json.loads(settings.read_text())
        assert document["model"] == "old"
        assert document["modelPicker"]["options"] == [
            {"model": "model-1", "label": "model 1"}
        ]
